  str_files_story_des_101 = "Todos, excepto Nikinis, han llenado el formulario de información básica. ¿Por se niega a rellenarlo...?",
  str_files_story_des_103 = "¡Inesperadamente, encontré a dos Nikinises! ¡¿Podría ser una de ellas la hermana mayor que sigue mencionando?! No las puedo distinguir...",
  str_files_story_des_105 = "Historia 5",
  str_files_story_des_107 = "Historia 7",
  str_files_story_des_110 = "Historia 10",
  str_files_story_des_201 = "Puedes sentir la mirada intensa de alguien siguiéndote a todas partes últimamente. Para atraer al acosador, finges ser un torpe...",
  str_files_story_des_203 = "Tu superior es sorprendentemente fácil de llevar, pero su poderosa aura aún te deja perplejo. Tienes una pregunta que no sabes si debes hacer...",
  str_files_story_des_205 = "Historia 5",
  str_files_story_des_207 = "Historia 7",
  str_files_story_des_209 = "Historia 9",
  str_files_story_des_210 = "Historia 10",
  str_files_story_des_402 = "Historia 2",
  str_files_story_des_404 = "Historia 4",
  str_files_story_des_406 = "Historia 6",
  str_files_story_des_408 = "Historia 8",
  str_files_story_des_501 = "Historia 1",
  str_files_story_des_503 = "Historia 3",
  str_files_story_des_505 = "Historia 5",
  str_files_story_des_507 = "Historia 7",
  str_files_story_des_509 = "Historia 9",
  str_files_story_des_510 = "Historia 10",
  str_files_story_des_602 = "Parece que no es tan fácil de lidiar con la hija del Señor de la Ciudad. Intentas mostrarle tus cualidades de líder, pero...",
  str_files_story_des_604 = "Carleen parece estar en un dilema. Dado lo poco que sabes leer a los demás, ¿cómo vas a abrirte paso?",
  str_files_story_des_606 = "Historia 6",
  str_files_story_des_608 = "Historia 8",
  str_files_story_des_609 = "Historia 9",
  str_files_story_des_610 = "Historia 10",
  str_files_story_des_802 = "Historia 2",
  str_files_story_des_804 = "Historia 4",
  str_files_story_des_806 = "Historia 6",
  str_files_story_des_901 = "Historia 1",
  str_files_story_des_903 = "Historia 3",
  str_files_story_des_905 = "Historia 5",
  str_files_story_des_907 = "Historia 7",
  str_files_story_des_910 = "Historia 10",
  str_files_story_des_1002 = "Historia 2",
  str_files_story_des_1004 = "Historia 4",
  str_files_story_des_1006 = "Historia 6",
  str_files_story_des_1008 = "Historia 8",
  str_files_story_des_1009 = "Historia 9",
  str_files_story_des_1102 = "Hoy no es un día de inspección regular, ¡pero sientes mucha presión porque Sharona, una Comandante de Illumina, va a comentar sobre las operaciones del Colossus! Esperemos que todo vaya bien...",
  str_files_story_des_1104 = "Sharona, que ha prestado mucha atención tanto al Colossus como a ti, parece tener sus propias razones. Tal vez ha visto algo en ti que satisface algunas de sus expectativas...",
  str_files_story_des_1106 = "Historia 5",
  str_files_story_des_1108 = "Historia 7",
  str_files_story_des_1110 = "Historia 10",
  str_files_story_des_1201 = "Se escuchan acalorados debates en el Colossus sobre asuntos triviales. Te guste o no, parece que tienes que ser el pacificador...",
  str_files_story_des_1203 = "La Srta. Nemesis parece tener una fuerte obsesión por la equidad y la justicia. Deberías dedicar más tiempo a charlar con ella para conocer su lado oculto...",
  str_files_story_des_1205 = "Historia 5",
  str_files_story_des_1207 = "Historia 7",
  str_files_story_des_1210 = "Historia 10",
  str_files_story_des_1302 = "Historia 2",
  str_files_story_des_1304 = "Historia 4",
  str_files_story_des_1306 = "Historia 6",
  str_files_story_des_1308 = "Historia 8",
  str_files_story_des_1309 = "Historia 9",
  str_files_story_des_1310 = "Historia 10",
  str_files_story_des_1402 = "¡¿El Señor de la Ciudad está revisando el Colossus en persona?! Nervioso, llegas tarde desde el principio. ¡Será mejor no cometas más errores!",
  str_files_story_des_1404 = "¿Por qué el amable señor de la ciudad se ha dirigido a ti de forma tan agresiva? ¿Qué está pasando? Como responsable del Colossus, vuelves a sentir una mirada que transmite tanto expectación como decepción...",
  str_files_story_des_1406 = "Historia 6",
  str_files_story_des_1408 = "Historia 8",
  str_files_story_des_1409 = "Historia 9",
  str_files_story_des_1410 = "Historia 10",
  str_files_story_des_1701 = "Historia 1",
  str_files_story_des_1703 = "Historia 3",
  str_files_story_des_1705 = "Historia 5",
  str_files_story_des_1707 = "Historia 7",
  str_files_story_des_1802 = "¿Una invitación a un evento de música en vivo? Mientras dudas si debes participar en este evento en vez de descansar, oyes violentos golpes en la puerta...",
  str_files_story_des_1804 = "Ha llegado el día. Te preguntas cómo será el evento de música en vivo de Regina, y empiezas a sentirte un poco inquieto—",
  str_files_story_des_1806 = "Historia 6",
  str_files_story_des_1808 = "Historia 8",
  str_files_story_des_1809 = "Historia 9",
  str_files_story_des_1810 = "Historia 10",
  str_files_story_des_1901 = "Historia 1",
  str_files_story_des_1903 = "Historia 3",
  str_files_story_des_1905 = "Historia 5",
  str_files_story_des_1907 = "Historia 7",
  str_files_story_des_1910 = "Historia 10",
  str_files_story_des_2101 = "Historia 1",
  str_files_story_des_2103 = "Historia 3",
  str_files_story_des_2105 = "Historia 5",
  str_files_story_des_2107 = "Historia 7",
  str_files_story_des_2201 = "Historia 1",
  str_files_story_des_2203 = "Historia 3",
  str_files_story_des_2205 = "Historia 5",
  str_files_story_des_2301 = "Historia 3",
  str_files_story_des_2303 = "Historia 5",
  str_files_story_des_2305 = "Historia 7",
  str_files_story_des_2307 = "Historia 9",
  str_files_story_des_2310 = "Historia 10",
  str_files_story_des_2501 = "Otro día de recibir numerosas quejas sobre Charon. Es hora de hablar con él.",
  str_files_story_des_2503 = "Es imposible mantener una conversación normal con Charon. Haz lo posible por obtener más información y puede que descubras su obsesión.",
  str_files_story_des_2505 = "Historia 5",
  str_files_story_des_2507 = "Historia 7",
  str_files_story_des_2509 = "Historia 9",
  str_files_story_des_2510 = "Historia 10",
  str_files_story_des_2602 = "Historia 2",
  str_files_story_des_2604 = "Historia 4",
  str_files_story_des_2606 = "Historia 6",
  str_files_story_des_2608 = "Historia 8",
  str_files_story_des_2609 = "Historia 9",
  str_files_story_des_2610 = "Historia 10",
  str_files_story_des_2801 = "Sigues sintiendo que algo malo va a pasar... ¿Qué es? Ah, ¿es esa Raphaela ahí? ¿Por qué está saludando...como loca?",
  str_files_story_des_2803 = "La búsqueda de Raphaela para mejorar los tratamientos médicos es molesta. Ojalá que no esté haciendo travesuras, o incluso tú presentarás una queja...",
  str_files_story_des_2805 = "Historia 5",
  str_files_story_des_2807 = "Historia 7",
  str_files_story_des_2809 = "Historia 9",
  str_files_story_des_2810 = "Historia 10",
  str_files_story_des_2902 = "Historia 2",
  str_files_story_des_2904 = "Historia 4",
  str_files_story_des_2906 = "Historia 6",
  str_files_story_des_2908 = "Historia 8",
  str_files_story_des_2909 = "Historia 9",
  str_files_story_des_2910 = "Historia 10",
  str_files_story_des_3202 = "Historia 2",
  str_files_story_des_3204 = "Historia 4",
  str_files_story_des_3206 = "Historia 6",
  str_files_story_des_3301 = "Pregunta: ¿Qué tanto conoces a esa vieja amiga con la que has salido todos los días? ¿Sabes lo que piensa? Quizá la respuesta esté enterrada...",
  str_files_story_des_3303 = "¿Por qué una encuesta con Vice se parece más a una crítica? Estás nervioso y esperas que Vice no te haga daño, independiente de lo que sea...",
  str_files_story_des_3305 = "Historia 6",
  str_files_story_des_3307 = "Historia 8",
  str_files_story_des_3310 = "Historia 10",
  str_files_story_des_3501 = "Eho ha sido muy impuntual con su entrega últimamente. ¿Por qué? Intenta hablar con ella sobre eso...",
  str_files_story_des_3503 = "Resulta ser que Eho tiene un mal sentido de dirección... Debe ser muy difícil para ella hacer su trabajo... ¿copiar mapas realmente la ayuda a recordar...?",
  str_files_story_des_3505 = "Historia 5",
  str_files_story_des_3602 = "Historia 1",
  str_files_story_des_3604 = "Historia 3",
  str_files_story_des_3606 = "Historia 5",
  str_files_story_des_3608 = "Historia 7",
  str_files_story_des_3610 = "Historia 10",
  str_files_story_des_3802 = "La Srta. Gronru se ha preocupado mucho por el mantenimiento del Colossus últimamente y parece estar muy interesada y entusiasmada con él. Ambos van a tener hoy la primera reunión oficial. ¿Me pregunto cómo es su personalidad?",
  str_files_story_des_3804 = "Parece que a la Srta. Gronru en verdad le gustan los juegos... Espero que esto no afecte su trabajo diario, si no será difícil de lidiar...",
  str_files_story_des_3806 = "Historia 6",
  str_files_story_des_3808 = "Historia 8",
  str_files_story_des_3809 = "Historia 9",
  str_files_story_des_3810 = "Historia 10",
  str_files_story_des_4001 = "Historia 1",
  str_files_story_des_4003 = "Historia 3",
  str_files_story_des_4005 = "Historia 5",
  str_files_story_des_4007 = "Historia 7",
  str_files_story_des_4101 = "La Srta. Blanc siempre está ocupada por los grandes eventos. ¿Por qué no la revisas? Es mejor si puedes ser de ayuda, en lugar de estorbar...",
  str_files_story_des_4103 = "Hmm... Parece que has empeorado las cosas. La Srta. Blanc está ahora más ocupada que antes... ¿Puedes compensarlo de alguna forma?",
  str_files_story_des_4105 = "Historia 5",
  str_files_story_des_4107 = "Historia 7",
  str_files_story_des_4402 = "Historia 2",
  str_files_story_des_4404 = "Historia 4",
  str_files_story_des_4406 = "Historia 6",
  str_files_story_des_4408 = "Historia 8",
  str_files_story_des_4601 = "Historia 1",
  str_files_story_des_4603 = "Historia 3",
  str_files_story_des_4605 = "Historia 5",
  str_files_story_des_4701 = "Zoya esta actuando de forma sospechosa últimamente, errática y esquiva. Parece que... ¿está observando algo?",
  str_files_story_des_4703 = "Así que Zoya depende de Madam Hiiro de una forma especial. ¿Me pregunto cómo surgió eso, y si ella compartirá la historia?",
  str_files_story_des_4705 = "Historia 5",
  str_files_story_des_4801 = "Como responsable del Colossus, la recopilación de información es también una descripción del trabajo, que parece aplicarse al viaje con Dayna.",
  str_files_story_des_4803 = "Claro, el trabajo de una caravana no es fácil... Luego de caminar con Dayna durante una distancia larga, apenas puedes mantenerte en pie, mucho menos recoger información...",
  str_files_story_des_4805 = "Historia 5",
  str_files_story_des_4807 = "Historia 7",
  str_files_story_des_4902 = "Historia 2",
  str_files_story_des_4904 = "Historia 4",
